function syncReportHeader(){$("reportHeaderNumber").textContent=$("reportNumber").value||"pendiente";$("headerReceptionDate").textContent=$("receivedDate").value?$("receivedDate").value.split("-").reverse().join("/"):"—";$("headerStartDate").textContent=$("startDate").value?$("startDate").value.split("-").reverse().join("/"):"—";$("headerEndDate").textContent=$("endDate").value?$("endDate").value.split("-").reverse().join("/"):"—";$("headerVet").textContent=$("vetName").value||"—"}
function renderWarnings(){if(!act)return;const w=[...act.warnings];if(act.labCode&&profile.labCode&&act.labCode!==profile.labCode)w.push(`El acta está dirigida a ${act.labCode}, pero Mis datos tiene ${profile.labCode}.`);if(!profile.labCode)w.push("Completá el código del laboratorio en Mis datos.");if(!$("vetName").value)w.push(`No se encontró el nombre del funcionario ${act.cuit||"sin CUIT"}. Podés agregarlo ahora.`);$("quickAddVet").hidden=!!$("vetName").value;$("parseWarnings").hidden=!w.length;$("parseWarnings").innerHTML=w.length?`<b>Revisiones pendientes</b><ul>${w.map(x=>`<li>${x}</li>`).join("")}</ul>`:""}
function sampleErrors(r){return[!r.categoryCode,!r.resultCode,!r.antigen,!r.brand,!r.lot,!r.expiry].filter(Boolean).length}function rowMatches(r,f){if(f==="all")return true;if(f==="errors")return sampleErrors(r)>0;return norm(resultLabel(r.resultCode))===f}function counts(rows){const by=x=>rows.filter(r=>norm(resultLabel(r.resultCode))===x).length;return{all:rows.length,negative:by("NEGATIVO"),positive:by("POSITIVO"),suspect:rows.filter(r=>["SOSPECHOSO","DUDOSO"].includes(norm(resultLabel(r.resultCode)))).length,errors:rows.filter(sampleErrors).length}}
const fields=["selected","tube","identifier","category","age","resultCode","resultNumber","antigen","brand","lot","expiry","stamp"],labels=["","Tubo","Identificación","Categoría","Edad","Resultado","Valor","Antígeno","Marca","Lote","Vencimiento","Estampilla"];
function headHtml(prefix="",config=primaryDiagnosis()){return `<tr>${labels.map((l,i)=>{if(i===0)return`<th><input type="checkbox" data-master="${prefix}" title="Seleccionar o deseleccionar todo"></th>`;const f=fields[i],canBulk=!['tube','identifier','resultNumber'].includes(f);return`<th class="${canBulk?'bulkable':''}" ${canBulk?`data-open-bulk="${prefix}" data-field="${f}"`:''}>${l}${canBulk?' ▾':''}</th>`}).join("")}</tr>`}
function rowResultClass(r){const result=norm(resultLabel(r.resultCode));return result==="POSITIVO"?"positive-row":["SOSPECHOSO","DUDOSO"].includes(result)?"suspect-row":""}
function rowHtml(r,i,confirm=false,config=primaryDiagnosis()){const di=confirm?`data-ci="${i}"`:`data-i="${i}"`,catOpts=categoryRows(act?.species,r.category).map(x=>`<option value="${x.Descripcion}" ${norm(x.Descripcion)===norm(r.category)?"selected":""}>${x.Descripcion}</option>`).join("");return `<tr class="${rowResultClass(r)}"><td><input type="checkbox" ${di} data-field="selected" ${r.selected?"checked":""}></td><td><input ${di} data-field="tube" value="${r.tube}"></td><td><input ${di} data-field="identifier" value="${r.identifier}"></td><td><select ${di} data-field="category" class="${r.categoryCode?"":"invalid"}">${catOpts}</select></td><td><input ${di} data-field="age" value="${r.age||"N/A"}"></td><td><select ${di} data-field="resultCode" class="${r.resultCode?"":"invalid"}">${resultOptions(r.resultCode,config)}</select></td><td><input inputmode="decimal" ${di} data-field="resultNumber" value="${r.resultNumber}" ${techniqueRule(config).value?'':'disabled'}></td><td><input ${di} data-field="antigen" value="${r.antigen}"></td><td><input ${di} data-field="brand" value="${r.brand}"></td><td><input ${di} data-field="lot" value="${r.lot}"></td><td><input type="date" ${di} data-field="expiry" value="${r.expiry}"></td><td><input ${di} data-field="stamp" value="${r.stamp}"></td></tr>`}
function renderSamples(){if(!act)return;const primary=primaryDiagnosis(),showValue=techniqueRule(primary).value;$("samplesHead").innerHTML=headHtml("",primary);$("samplesHead").closest("table").classList.toggle("hide-value",!showValue);$("samplesBody").innerHTML=samples.map((r,i)=>({r,i})).filter(x=>rowMatches(x.r,filter)).map(x=>rowHtml(x.r,x.i,false,primary)).join("");const c=counts(samples);for(const [id,v] of [["countAll",c.all],["countNegative",c.negative],["countPositive",c.positive],["countSuspect",c.suspect],["countErrors",c.errors]])$(id).textContent=v;document.querySelector('[data-result-filter="POSITIVO"]')?.classList.add('positive-filter');$("validSummary").textContent=c.errors?`${c.errors} para revisar`:`${samples.length} completas`;$("readyTitle").textContent=c.errors?"Hay datos para revisar":"Protocolo listo";$("readyDetail").textContent=c.errors?"Excel y PDF pueden descargarse; el JSON requiere completar los datos.":"Revisá una vez más antes de descargar.";$("downloadJson").disabled=c.errors>0||headerErrors().length>0;renderConfirmatory()}
function renderConfirmatory(){if(!confirmatory){$("confirmatoryPanel").hidden=true;return}$("confirmatoryPanel").hidden=false;$("confirmatoryTitle").textContent=confirmatory.technique.technique;$("confirmatoryHead").innerHTML=headHtml("confirm",confirmatory.technique);$("confirmatoryBody").innerHTML=confirmatory.rows.map((r,i)=>({r,i})).filter(x=>rowMatches(x.r,confirmFilter)).map(x=>rowHtml(x.r,x.i,true,confirmatory.technique)).join("");$("confirmatoryHead").closest("table").classList.toggle("hide-value",!techniqueRule(confirmatory.technique).value);const c=counts(confirmatory.rows);$("confirmatoryCounters").innerHTML=`<button data-cfilter="all" class="${confirmFilter==="all"?"active":""}">Todas <b>${c.all}</b></button><button data-cfilter="NEGATIVO">Negativas <b>${c.negative}</b></button><button data-cfilter="POSITIVO" class="positive-filter">Positivas <b>${c.positive}</b></button><button data-cfilter="SOSPECHOSO">Sospechosas <b>${c.suspect}</b></button><button data-cfilter="errors">Para revisar <b>${c.errors}</b></button>`}
function applyHeader(target,field,value){const rows=target==="confirm"?confirmatory?.rows:samples;if(!rows||value==="")return;for(const r of rows){r[field]=value;if(field==="category")r.categoryCode=categoryRows(act.species,value).find(x=>norm(x.Descripcion)===norm(value))?.["#"]||codeByDescription("categories",value)}renderSamples();toast("Valor aplicado a todas las muestras.")}
function openBulk(button){document.querySelector(".bulk-popover")?.remove();const field=button.dataset.field,target=button.dataset.openBulk,config=target==="confirm"?confirmatory?.technique:primaryDiagnosis(),box=document.createElement("div");box.className="bulk-popover";const label=labels[fields.indexOf(field)],control=field==="resultCode"?`<select>${resultOptions("",config)}</select>`:field==="category"?`<select><option value="">Seleccionar…</option>${categoryRows(act.species).map(r=>`<option>${r.Descripcion}</option>`).join("")}</select>`:`<input ${field==="expiry"?'type="date"':''}>`;box.innerHTML=`<label>Aplicar ${label.toLowerCase()} a todas</label>${control}<button>Aplicar</button>`;const rect=button.getBoundingClientRect();box.style.left=Math.min(rect.left,innerWidth-280)+"px";box.style.top=Math.min(rect.bottom+5,innerHeight-150)+"px";box.querySelector("button").onclick=()=>{applyHeader(target,field,box.querySelector("select,input").value);box.remove()};document.body.append(box);box.querySelector("select,input").focus()}
function addConfirmatory(){const positives=samples.filter(r=>norm(resultLabel(r.resultCode))==="POSITIVO"),selected=samples.filter(r=>r.selected),custom=selected.length>0&&selected.length<samples.length,base=custom?selected:(positives.length?positives:selected);if(!base.length)return toast("Marcá las muestras o cargá primero los resultados positivos.");const primary=primaryDiagnosis(),options=(recognizedDiagnostic()?.techniques||[]).filter(t=>t!==primary&&t.code);if(!options.length)return toast("Agregá una técnica confirmatoria con su código dentro del diagnóstico en Mis datos.");const answer=prompt(`Técnica adicional:\n${options.map((d,i)=>`${i+1}. ${d.technique}`).join("\n")}\n\nSe incluirán ${custom?"las muestras seleccionadas":positives.length?"las positivas":"las seleccionadas"}. Escribí el número:`,"1"),technique=options[Number(answer)-1];if(!technique)return;confirmatory={technique,rows:base.map(r=>prefill({...r,selected:false,resultCode:"",resultNumber:""},technique))};renderSamples()}
function renderDirectors(){$("director").innerHTML='<option value="">Seleccionar…</option>'+profile.directors.filter(d=>d.name||d.code).map(d=>`<option value="${d.code}">${d.name||"Sin nombre"} · ${d.code}</option>`).join("");const first=profile.directors.find(d=>d.code);if(first)$("director").value=first.code;$("conclusion").innerHTML='<option value="">Seleccionar…</option>'+profile.conclusions.map(c=>`<option>${c}</option>`).join("");if(profile.conclusions.length)$("conclusion").value=profile.conclusions[0]}
function diagnosticOptions(value){return `<option value="">Seleccionar diagnóstico…</option>${diagnosticCatalog.map(d=>`<option ${norm(d.name)===norm(value)?"selected":""}>${d.name}</option>`).join("")}`}function techniquesFor(name){const d=diagnosticCatalog.find(x=>norm(x.name)===norm(name)),all=catalog("techniques");if(!d)return all;const matches=[];for(const wanted of d.techniques){const exact=all.find(r=>norm(r.Descripcion)===norm(wanted)),partial=all.find(r=>norm(r.Descripcion).includes(norm(wanted))||norm(wanted).includes(norm(r.Descripcion)));if(exact||partial)matches.push(exact||partial)}return matches.length?matches:all.filter(r=>d.techniques.some(t=>norm(r.Descripcion).includes(norm(t))))}function techniqueOptions(value,diagnosis){const rows=techniquesFor(diagnosis),current=catalog("techniques").find(r=>norm(r.Descripcion)===norm(value));if(current&&!rows.some(r=>norm(r.Descripcion)===norm(value)))rows.unshift(current);return `<option value="">Seleccionar técnica…</option>${rows.map(r=>`<option value="${r.Descripcion}" ${norm(r.Descripcion)===norm(value)?"selected":""}>${r.Descripcion}</option>`).join("")}`}
function renderProfile(){$("labName").value=profile.labName;$("labCode").value=profile.labCode;$("labAddress").value=profile.labAddress;$("labEmail").value=profile.labEmail;$("labPhone").value=profile.labPhone||"";$("conclusions").value=profile.conclusions.join("\n");$("directorsList").innerHTML=profile.directors.map((d,i)=>`<div class="repeat-row"><input data-director="name" data-i="${i}" placeholder="Nombre" value="${d.name}"><input data-director="code" data-i="${i}" placeholder="Código GRECERT" value="${d.code}"><button class="remove" data-remove-director="${i}">×</button></div>`).join("");$("diagnosesList").innerHTML=profile.diagnoses.map((d,i)=>`<section class="diagnosis-card"><div class="diagnosis-card-head"><label>Diagnóstico<select data-diagnostic-name data-di="${i}">${diagnosticOptions(d.name)}</select></label><div><button class="add-technique" data-add-technique="${i}">+ Agregar técnica</button><button class="remove" data-remove-diagnosis="${i}">Eliminar diagnóstico</button></div></div><div>${d.techniques.map((t,j)=>`<div class="technique-row"><label>Técnica<select data-technique="technique" data-di="${i}" data-ti="${j}">${techniqueOptions(t.technique,d.name)}</select></label><label>Cód. ensayo<input inputmode="numeric" data-technique="code" data-di="${i}" data-ti="${j}" value="${t.code||""}"></label>${["antigen","brand","lot","expiry","stamp"].map(f=>`<label>${({antigen:"Antígeno",brand:"Marca",lot:"Lote",expiry:"Vencimiento",stamp:"Estampilla"})[f]}<input ${f==="expiry"?'type="date"':''} data-technique="${f}" data-di="${i}" data-ti="${j}" value="${t[f]||""}"></label>`).join("")}<button class="remove" data-remove-technique="${i}:${j}">×</button></div>`).join("")}</div></section>`).join("")}
function readProfile(){for(const id of ["labName","labCode","labAddress","labEmail","labPhone"])profile[id]=$(id).value.trim();profile.labCode=profile.labCode.toUpperCase();profile.conclusions=$("conclusions").value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);document.querySelectorAll("[data-director]").forEach(e=>profile.directors[+e.dataset.i][e.dataset.director]=e.value.trim());document.querySelectorAll("[data-diagnostic-name]").forEach(e=>profile.diagnoses[+e.dataset.di].name=e.value);document.querySelectorAll("[data-technique]").forEach(e=>profile.diagnoses[+e.dataset.di].techniques[+e.dataset.ti][e.dataset.technique]=e.value.trim());persist()}
function allVeterinarians(){return{...registryVets,...profile.veterinarians}}function renderVets(){const q=norm($("vetSearch").value),custom=Object.entries(profile.veterinarians),source=q.length>=3?Object.entries(allVeterinarians()).filter(([c,v])=>norm(c+" "+v.name).includes(q)).slice(0,100):custom;const entries=source.sort((a,b)=>a[1].name.localeCompare(b[1].name));$("vetCount").textContent=q.length>=3?`${entries.length} coincidencias`:`${custom.length} propios · ${Object.keys(registryVets).length} sugerencias SENASA`;$("vetList").innerHTML=entries.map(([c,v])=>`<div class="vet-row"><b>${v.name}</b><span>${c}${v.locality?` · ${v.locality}`:""}</span>${profile.veterinarians[c]?`<button class="remove" data-remove-vet="${c}">Eliminar</button>`:"<small>Registro SENASA</small>"}</div>`).join("");$("vetNames").innerHTML=Object.entries(allVeterinarians()).map(([c,v])=>`<option value="${v.name}">${c}</option>`).join("")}
function addVet(name,cuit){name=String(name).trim();cuit=formatCuit(cuit);if(!name||cuit.replace(/\D/g,"").length!==11)return toast("Completá nombre y CUIT válido.");profile.veterinarians[cuit]={name};persist();renderVets();toast("Veterinario guardado.")}
async function importVets(file){const wb=XLSX.read(await file.arrayBuffer()),rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:""});let added=0;for(const row of rows){const cuitCell=row.find(v=>String(v).replace(/\D/g,"").length===11);if(!cuitCell)continue;const nameCell=row.find(v=>v!==cuitCell&&/[A-Za-zÁÉÍÓÚÑáéíóúñ]{3}/.test(String(v)));if(nameCell){profile.veterinarians[formatCuit(cuitCell)]={name:String(nameCell).trim()};added++}}persist();renderVets();toast(`${added} veterinarios importados como sugerencias.`)}
function headerErrors(){return[!profile.labCode&&"Código de laboratorio",!$("reportNumber").value&&"Número de informe",!$("director").value&&"Director técnico",!$("conclusion").value&&"Conclusión",!act?.actNumber&&"Número de acta"].filter(Boolean)}function makeAnalysis(t,rows){if(!Number(t?.code))throw Error(`Falta el código de ensayo para ${t?.technique||"la técnica"}.`);return{codigoEnsayo:Number(t.code),resultadoUnico:false,fechaInicio:dateTime($("startDate").value),fechaFin:dateTime($("endDate").value),subMuestras:rows.map(r=>{const x={codigoResultadoLetra:Number(r.resultCode),identificacion:r.identifier||r.tube||"S/N",codigoTipoIdentificacion:Number(r.idTypeCode||12),codigoDeEdad:Number(sampleReader.ageCode(r.age,catalog("ages"))),codigoDeCategoria:Number(r.categoryCode),antigeno:r.antigen,marcaDeAntigeno:r.brand,lote:r.lot,fechaDeVencimientoDeAnalisis:dateTime(r.expiry)};if(r.resultNumber!=="")x.resultadoNumero=Number(r.resultNumber);if(r.stamp)x.estampilla=r.stamp;return x})}}
function makeJson(){const e=headerErrors(),p=primaryDiagnosis();if(e.length)throw Error(`Falta completar: ${e.join(", ")}.`);if(!p?.code)throw Error("Falta asociar la técnica principal con su código en Mis datos.");const mc=codeByDescription("motives",act.motive),sc=codeByDescription("submotives",act.submotive),pc=productCode(act.species);if(!mc||!sc||!pc){const missing=[!mc&&`motivo (${act.motive||"vacío"})`,!sc&&`submotivo (${act.submotive||"vacío"})`,!pc&&`especie (${act.species||"vacía"})`].filter(Boolean);throw Error(`No se pudo asociar con GRECERT: ${missing.join(", ")}.`)}const analyses=[makeAnalysis(p,samples)];if(confirmatory)analyses.push(makeAnalysis(confirmatory.technique,confirmatory.rows));return[{numeroInforme:$("reportNumber").value.trim(),codigoLaboratorio:profile.labCode,renspaUnidadProductiva:act.renspa,codigoMotivo:Number(mc),codigoSubMotivo:Number(sc),codigotipoDocumentoUno:21,numeroDocumentoUno:act.actNumber,cuitDeFuncionario:formatCuit($("vetCuit").value),muestra:{fechaDeToma:dateTime(isoDate(act.sampleDate)),fechaDeRecepcion:dateTime($("receivedDate").value),codigoDeProducto:pc,cantidadDeLote:samples.length,codigoUnidadDeMedidaDeLote:36,analisis:analyses,codigoDirectorTecnico:Number($("director").value),conclusionTramite:$("conclusion").value},codigoTipoDeTramite:3}]}
