async function readJsonFiles(files){merged=[];const reports=[];for(const file of files)try{const data=JSON.parse(await file.text()),items=Array.isArray(data)?data:[data];if(!items.every(x=>x?.muestra))throw Error("estructura no reconocida");merged.push(...items);reports.push({name:file.name,count:items.length,ok:true})}catch(e){reports.push({name:file.name,ok:false,error:e.message})}const nums=merged.map(x=>String(x.numeroInforme||"")),dup=[...new Set(nums.filter((x,i)=>x&&nums.indexOf(x)!==i))];$("mergeEmpty").hidden=true;$("mergeSummary").hidden=false;$("mergeFiles").textContent=reports.filter(r=>r.ok).length;$("mergeReports").textContent=merged.length;$("mergeSamples").textContent=merged.reduce((s,r)=>s+(r.muestra.analisis?.reduce((a,x)=>a+(x.subMuestras?.length||0),0)||0),0);$("mergeDuplicates").textContent=dup.length;$("mergeList").innerHTML=reports.map(r=>`<li>${r.ok?"✓":"⚠"} ${r.name}</li>`).join("");$("mergeDownload").disabled=!merged.length||dup.length>0}
