function renderDiagnosisAccordion(){const host=$("diagnosesList");const requestedOpen=diagnosisToOpen;host.innerHTML=profile.diagnoses.length?profile.diagnoses.map((d,i)=>`<details class="diagnosis-accordion" ${requestedOpen===i?"open":""}><summary><span>${d.name}</span><div class="diagnosis-tools"><button type="button" class="add-technique" data-add-technique="${i}">+ Agregar técnica</button><button type="button" class="remove" data-remove-diagnosis="${i}">Eliminar</button></div></summary><div class="diagnosis-body">${d.techniques.length?d.techniques.map((t,j)=>`<div class="technique-row"><label>Técnica<select data-technique="technique" data-di="${i}" data-ti="${j}">${techniqueOptions(t.technique,d.name)}</select></label><label>Cód. ensayo<input inputmode="numeric" data-technique="code" data-di="${i}" data-ti="${j}" value="${t.code||""}"></label>${["antigen","brand","lot","expiry","stamp"].map(f=>`<label>${({antigen:"Antígeno",brand:"Marca",lot:"Lote",expiry:"Vencimiento",stamp:"Estampilla"})[f]}<input ${f==="expiry"?'type="date"':''} data-technique="${f}" data-di="${i}" data-ti="${j}" value="${t[f]||""}"></label>`).join("")}<button type="button" class="remove" data-remove-technique="${i}:${j}" aria-label="Quitar técnica">×</button></div>`).join(""):`<div class="diagnosis-empty">Todavía no agregaste técnicas para este diagnóstico.</div>`}</div></details>`).join(""):`<div class="diagnosis-empty">Todavía no seleccionaste diagnósticos para el laboratorio.</div>`;diagnosisToOpen=null}
