function requestDiagnosticText(data){return norm(data.pages.flatMap(p=>p.lines).join(" "))}
const originalParseActa=parseActa;
parseActa=function(data,fileName){const result=originalParseActa(data,fileName),lines=data.pages.flatMap(p=>p.lines),start=lines.findIndex(l=>/^Solicitud de Análisis/i.test(l)),end=lines.findIndex((l,i)=>i>start&&/^ANEXO CON LAS MUESTRAS/i.test(l)),request=norm(lines.slice(start<0?0:start,end>start?end:lines.length).join(" "));result.area=(lines.find(l=>/^Programa de /i.test(l))||"").trim();result.diagnosticText=diagnosticCatalog.flatMap(d=>[d.name,...d.matches]).find(name=>request.includes(norm(name)))||"";if(!result.samples.length){const sampleLines=lines.slice(lines.findIndex(l=>/^ANEXO CON LAS MUESTRAS/i.test(l))+1),parsed=[];for(const line of sampleLines){let m=line.match(/^\s*(\w+)\s+(\d+)\s+(\d{8,})\s+(Animal sano|Animal enfermo|Animal caído|Animal muerto)\s+(.+?)(?:\s+\d{2}\/\d{2}\/\d{4})?\s*$/i);if(m){const category=m[5].replace(/\/N\/A.*$/i,"").trim();parsed.push({selected:false,tube:m[2],identifier:m[3],identificationType:m[4],category,categoryCode:categoryRows(result.species,category)[0]?.["#"]||"",age:"",resultCode:"",resultNumber:"",antigen:"",brand:"",lot:"",expiry:"",stamp:"",idTypeCode:1});continue}m=line.match(/^\s*(\d+)\s+(Animal sano|Animal enfermo|Animal caído|Animal muerto)\s+(.+?)(?:\s+\d{2}\/\d{2}\/\d{4})?\s*$/i);if(m){const category=m[3].replace(/\/N\/A.*$/i,"").trim();parsed.push({selected:false,tube:m[1],identifier:"",identificationType:m[2],category,categoryCode:categoryRows(result.species,category)[0]?.["#"]||"",age:"",resultCode:"",resultNumber:"",antigen:"",brand:"",lot:"",expiry:"",stamp:"",idTypeCode:12})}}if(parsed.length){result.samples=parsed;result.warnings=result.warnings.filter(w=>!w.includes("interpretaron")&&!w.includes("filas de muestras"))}}return result};
function configuredDiagnosticFor(currentAct){const explicit=norm(currentAct?.diagnosticText||"");let definition=diagnosticCatalog.find(d=>explicit===norm(d.name)||d.matches.some(m=>explicit===norm(m)));const text=norm(`${currentAct?.area||""} ${currentAct?.motive||""} ${currentAct?.submotive||""} ${currentAct?.diagnosticText||""} ${(currentAct?.techniques||[]).join(" ")} ${currentAct?.species||""}`);if(!definition)definition=norm(currentAct?.area||"").includes("SANIDAD AVICOLA")?diagnosticCatalog.find(d=>d.name==="INFLUENZA AVIAR"):diagnosticCatalog.find(d=>d.matches.some(m=>text.includes(norm(m))));if(!definition&&text.includes("EQUIDO")&&(text.includes("IDGA")||text.includes("ANEMIA")))definition=diagnosticCatalog.find(d=>d.name==="ANEMIAS");return definition&&profile.diagnoses.find(d=>norm(d.name)===norm(definition.name))||null}
recognizedDiagnostic=function(){return configuredDiagnosticFor(act)};

function upgradeProtocolHeader(){const oldGrid=document.querySelector(".report-grid"),oldPanel=oldGrid?.closest("section.panel"),header=document.querySelector(".report-header");if(!oldPanel||!header)return;const move=(inputId,placeholderId)=>{const input=$(inputId),placeholder=$(placeholderId);if(input&&placeholder)placeholder.replaceWith(input)};move("reportNumber","reportHeaderNumber");move("receivedDate","headerReceptionDate");move("startDate","headerStartDate");move("endDate","headerEndDate");move("vetName","headerVet");const directorWrap=document.createElement("label");directorWrap.className="report-director";directorWrap.innerHTML="<span>Director técnico</span>";directorWrap.append($("director"));$("reportLabName").after(directorWrap);const vetParagraph=$("vetName").closest("p"),cuitParagraph=document.createElement("p");cuitParagraph.innerHTML="<b>CUIT veterinario:</b>";cuitParagraph.append($("vetCuit"));vetParagraph.after(cuitParagraph);document.querySelector("#establishment")?.closest("p")?.remove();const conclusionPanel=document.createElement("section");conclusionPanel.className="panel conclusion-panel";const conclusionLabel=document.createElement("label");conclusionLabel.innerHTML="<span>Conclusión del protocolo</span>";conclusionLabel.append($("conclusion"));conclusionPanel.append(conclusionLabel);document.querySelector(".samples-panel").before(conclusionPanel);$("quickAddVet").classList.add("header-add-vet");vetParagraph.after($("quickAddVet"));for(const [id,field] of [["motive","motive"],["submotive","submotive"],["species","species"],["holderDetail","holder"],["renspa","renspa"],["locality","locality"],["headerSampleDate","sampleDate"]]){const el=$(id);el.contentEditable="true";el.dataset.actField=field;el.title="Hacé clic para corregir"}oldPanel.remove()}

