function validateActFormat(data,parsed){
 const raw=data.pages.flatMap(p=>p.lines||[]).join('\n'),issues=[];
 const required=[
  [/ACTA DE TOMA DE MUESTRAS N[º°]/i,'No se encontró el encabezado del acta.'],
  [/Solicitud de Análisis/i,'No se encontró la sección Solicitud de Análisis.'],
  [/ANEXO CON LAS MUESTRAS/i,'No se encontró el anexo de muestras.'],
  [/Animales Muestreados:\s*\d+/i,'No se encontró la cantidad declarada de muestras.'],
  [/Nro\. Tubo\s+Identificación\s+Animal\s+Categoría\/edad\s+Fec\.vacuna\s+Observaciones/i,'Cambió el encabezado de la tabla de muestras.'],
  [/Número de acta\s+Código de cierre/i,'No se encontró el cierre reglamentario del acta.']
 ];
 for(const [pattern,message] of required)if(!pattern.test(raw))issues.push(message);
 const cells=data.pages.flatMap(p=>Array.isArray(p.sampleCells)?p.sampleCells:[]);
 if(!cells.length)issues.push('No se reconoció la estructura de columnas de las muestras.');
 if(parsed.amount!==parsed.samples.length)issues.push(`El acta declara ${parsed.amount} muestras, pero se interpretaron ${parsed.samples.length}.`);
 if(parsed.samples.some(r=>!r.tube||!r.categoryCode||sampleReader.ageCode(r.age,catalog('ages'))===''))issues.push('Una o más filas cambiaron de estructura o no permiten reconocer categoría y edad.');
 return {valid:issues.length===0,issues:[...new Set(issues)]};
}
